from scipy.optimize import least_squares
def run(fn,starts):
    best=None
    for s in starts:
        r=least_squares(fn,s)
        e=np.mean(r.fun**2)/np.var(dv_dt)
        if best is None or e<best[0]: best=(e,np.round(r.x,5))
    return best
def mkM(ph,env):
    return np.column_stack([np.ones_like(t),x,v,env*np.sin(ph),env*np.cos(ph)])
def fa(p):
    w,g=p; M=mkM(w*t,np.exp(-g*t)); c,_,_,_=np.linalg.lstsq(M,dv_dt,rcond=None); return M@c-dv_dt
def fb(p):
    w,b=p; M=mkM(w*t+b*t**2,1.0); c,_,_,_=np.linalg.lstsq(M,dv_dt,rcond=None); return M@c-dv_dt
